import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';import 'care_log_editor_screen.dart';
class CareTimelineScreen extends ConsumerWidget{const CareTimelineScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final logs=pet==null?<CareLog>[]:c.items('care_logs').map(CareLog.fromMap).where((e)=>e.petId==pet.id).toList()..sort((a,b)=>b.at.compareTo(a.at));return Scaffold(appBar:AppBar(title:const Text('Care timeline'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CareLogEditorScreen())),icon:const Icon(Icons.add))]),body:logs.isEmpty?const Center(child:Text('Your care notes will appear here.')):ListView(padding:const EdgeInsets.all(16),children:logs.map((e)=>Card(child:ListTile(leading:const Icon(Icons.notes,color:Color(0xFF39845A)),title:Text(e.title),subtitle:Text('${e.type} · ${DateFormat.yMMMd().add_jm().format(e.at)}${e.note.isEmpty?'':'\n'+e.note}')))).toList()));}}
